cat > .local/smart-shorts-seven/caption-probe.test.ts <<'EOF'
import {test,expect} from 'bun:test';
import {readFileSync} from 'node:fs';
import {getWordElementRefs} from '../../classic/apps/web/src/timeline/components/caption-word-element-refs';
const p=JSON.parse(readFileSync('/Users/itayzrihan/Documents/PoCut/.local/smart-shorts-seven/project-before.json','utf8'));
test('real saved caption UI references',()=>{
 const sourceTracks=p.scenes[0].tracks.overlay;
 const words=sourceTracks[0].captionSource.words;
 const start=performance.now();
 const refs=getWordElementRefs({words,sourceTracks});
 expect(refs.size).toBeGreaterThan(13000);
 console.log(JSON.stringify({words:words.length,referencedWords:refs.size,ms:performance.now()-start}));
});
EOF
cd classic/apps/web && bun test --preload ./test-support/real-wasm.ts ../../../.local/smart-shorts-seven/caption-probe.test.ts

